// intent: Exercises all supported valid type name lookups via bjd_type_name to ensure complete coverage of valid data types.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>
#include <utility>
int main() {
    std::vector<std::uint8_t> const data;
    using reader_t = nlohmann::detail::binary_reader<nlohmann::json, decltype(nlohmann::detail::input_adapter(data))>;
    const std::vector<char> types = {'B', 'C', 'D', 'I', 'L', 'M', 'U', 'd', 'i', 'l', 'm', 'u', 'x'};
    for (char t : types) {
        const char* name = reader_t::bjd_type_name(static_cast<unsigned char>(t));
        std::cout << t << ": " << (name ? name : "nullptr") << std::endl;
    }
}
